/* Example: Check and maximize the soft limit for open file descriptors (RLIMIT_NOFILE). */
#include <stdio.h>
#include <stdlib.h>
#include <sys/resource.h>
#include <errno.h>

#define RESOURCE RLIMIT_NOFILE

int main() {
    struct rlimit limits_struct;

    // 1. Get current limits for RLIMIT_NOFILE
    if (getrlimit(RESOURCE, &limits_struct) == -1) {
        perror("getrlimit failed");
        return EXIT_FAILURE;
    }

    printf("Current RLIMIT_NOFILE limits:\n");
    printf("  Soft Limit (rlim_cur): %lu\n", (unsigned long)limits_struct.rlim_cur);
    printf("  Hard Limit (rlim_max): %lu\n", (unsigned long)limits_struct.rlim_max);

    // 2. Attempt to raise the soft limit up to the current hard limit
    if (limits_struct.rlim_cur < limits_struct.rlim_max) {

        // Set new soft limit equal to hard limit
        limits_struct.rlim_cur = limits_struct.rlim_max;

        if (setrlimit(RESOURCE, &limits_struct) == -1) {
            if (errno == EPERM) {
                fprintf(stderr, "\nError: Cannot set limit. Requires root privileges to raise hard limit.\n");
            } else {
                perror("setrlimit failed");
                return EXIT_FAILURE;
            }
        } else {
            // Verification step
            getrlimit(RESOURCE, &limits_struct);
            printf("\nSuccessfully raised soft limit.\n");
            printf("  New Soft Limit: %lu\n", (unsigned long)limits_struct.rlim_cur);
        }
    } else {
        printf("\nSoft limit is already at maximum (Hard Limit).\n");
    }

    return EXIT_SUCCESS;
}
